// Pseudo-test harness for idempotent order creation and event replay
async function testIdempotentPostOrder(orderPayload) {
  const id = await postOrder(orderPayload);
  // retry with same payload
  const id2 = await postOrder(orderPayload);
  if (id !== id2) throw new Error('Idempotency key not preserved');
  const state = await getOrder(id);
  if (!state || state.status !== 'CONFIRMED') throw new Error('Order not final');
}
